--
-- Table structure for table `noticias`
--

DROP TABLE IF EXISTS `noticias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `noticias` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_id` int(10) unsigned NOT NULL,
  `titulo` varchar(90) NOT NULL,
  `resumo` varchar(180) NOT NULL,
  `texto` mediumtext NOT NULL,
  `tipo` enum('','acao_realizada','projeto','campanha','evento','agradecimento','prestacao_contas') NOT NULL DEFAULT '',
  `estado` enum('rascunho','publicada','oculta') NOT NULL DEFAULT 'rascunho',
  `slug` varchar(120) NOT NULL,
  `projeto_id` int(10) unsigned DEFAULT NULL,
  `movimentacao_id` int(10) unsigned DEFAULT NULL,
  `evento_data` datetime DEFAULT NULL,
  `evento_local` varchar(200) DEFAULT NULL,
  `direitos_imagem_aceito_em` datetime DEFAULT NULL,
  `criado_em` datetime NOT NULL DEFAULT current_timestamp(),
  `atualizado_em` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `publicada_em` datetime DEFAULT NULL,
  `ocultada_em` datetime DEFAULT NULL,
  `ocultada_por` int(10) unsigned DEFAULT NULL,
  `ocultacao_categoria` varchar(40) DEFAULT NULL,
  `ocultacao_mensagem` text DEFAULT NULL,
  `demonstracao` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_noticias_estado_data` (`estado`,`publicada_em`),
  KEY `idx_noticias_usuario_estado` (`usuario_id`,`estado`),
  KEY `idx_noticias_tipo_estado` (`tipo`,`estado`),
  KEY `idx_noticias_criado` (`criado_em`),
  KEY `idx_noticias_demonstracao` (`demonstracao`),
  KEY `idx_noticias_projeto` (`projeto_id`),
  KEY `idx_noticias_movimentacao` (`movimentacao_id`),
  KEY `idx_noticias_ocultada_por` (`ocultada_por`),
  CONSTRAINT `fk_noticias_movimentacao` FOREIGN KEY (`movimentacao_id`) REFERENCES `movimentacoes` (`id`) ON DELETE SET NULL,
